import {requireAccount,currentUser,saveRun} from './account.js';
import {newGame,update,unlock,gates,gaps,platforms,WORLD,FLOOR} from './engine.mjs';
import {questions} from './questions.js';
import {frames,pose} from './poses.mjs';
const motion=new Image();motion.src='assets/danbi-motion.png';
const app=document.getElementById('app'),info=document.getElementById('info'),sprite=new Image();sprite.src='assets/danbi-fox.png';
let mode='solo',state,canvas,ctx,scene='home',paused=false,quizIndex=null,quizSolved=false,wrong=false,firstTry=0,keys={},last=0,raf=0,camera=0,sound=true,audio,gatePrompt=-1,returnFocus;
const music=new Audio('assets/danbi-adventure.wav');music.loop=true;music.preload='auto';music.volume=.3;music.id='bgm';music.hidden=true;music.setAttribute('aria-hidden','true');document.body.append(music);
function syncMusic(){const active=scene==='game'&&sound&&!paused&&!info.open&&!document.hidden;music.volume=quizIndex!==null?.09:.3;if(active){music.play().catch(()=>{const b=document.getElementById('sound');if(b){b.textContent='♪ 음악 재생';b.setAttribute('aria-label','음악 재생 다시 시도');}});}else music.pause();}
let learningRunId=null,learningOwner=null;
function saveLearning(completed=false){if(!state||!learningRunId||!learningOwner)return;saveRun({id:learningRunId,user_id:learningOwner,mode,coins:state.count,solved:state.solved,first_try:firstTry,completed,elapsed_seconds:Math.min(86400,Math.round(state.time))});}
document.addEventListener('account-changed',()=>{if(scene==='game'||scene==='finish'){learningRunId=null;learningOwner=null;home();}});
document.addEventListener('account-dialog-open',()=>{if(scene==='game')setPause(true);});
const chapters=['백성의 마을','궁궐의 연구실','글자의 방','시간의 문','유물 보관실'];
function clearInput(){keys={};if(state)state.jumpHeld=false;document.querySelectorAll('.pressed').forEach(b=>b.classList.remove('pressed'));}
function tone(hz=750,duration=.08){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=hz;g.gain.setValueAtTime(.06,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{sound=false;}}
function stop(){cancelAnimationFrame(raf);clearInput();music.pause();}
function focusHeading(){const h=app.querySelector('h1,h2');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}}
function home(){stop();scene='home';state=null;app.className='';app.innerHTML=`<section class="landing"><div class="intro"><div class="eyebrow">조선 편 · 세종과 훈민정음</div><h1>달리고, 뛰고,<br><em>역사를 찾아!</em></h1><p>단비와 떠나는 시간여행.<br>코인을 모으고 역사 문을 열어<br>훈민정음을 되찾아 주세요.</p><div class="mode-switch" aria-label="플레이 모드"><button data-mode="solo" aria-pressed="${mode==='solo'}">개인 탐험</button><button data-mode="class" aria-pressed="${mode==='class'}">우리 반 탐험</button></div><button id="start" class="primary">탐험 시작하기 <span>→</span></button><div class="hintline">← → 이동 · Space 점프 · 터치 조작 가능</div></div><div class="preview"><div class="preview-tag">STAGE 01 <span>1443 → 1446</span></div><canvas id="preview" width="960" height="540" aria-label="조선 궁궐과 코인이 있는 횡스크롤 게임 미리보기"></canvas><div class="preview-caption"><strong>✦ 훈민정음의 비밀</strong><span>코인 수집 + 점프 탐험 + 역사 미션</span></div></div></section><section class="features"><div><b>01</b><span><strong>단비를 직접 움직여요</strong><small>발판에 올라 코인을 모으세요</small></span></div><div><b>02</b><span><strong>역사 문을 열어요</strong><small>다섯 문제를 풀면 길이 열려요</small></span></div><div><b>03</b><span><strong>훈민정음을 되찾아요</strong><small>궁궐 끝에 숨은 유물을 찾아요</small></span></div></section>`;app.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;home();});document.getElementById('start').onclick=start;canvas=document.getElementById('preview');ctx=canvas.getContext('2d');const demo=newGame();demo.player.x=380;demo.player.y=288;demo.player.ground=false;draw(demo,0);sprite.onload=()=>{if(scene==='home')draw(demo,0);};}
async function start(){if(!await requireAccount())return;stop();state=newGame();learningRunId=crypto.randomUUID();learningOwner=currentUser();scene='game';music.currentTime=0;paused=false;quizIndex=null;firstTry=0;gatePrompt=-1;camera=0;app.className=mode==='class'?'classroom':'';app.innerHTML=`<section class="play-shell"><div class="game-top"><div><span class="stage-label">조선 · 세종과 훈민정음</span><strong id="chapter">백성의 마을</strong></div><div class="hud"><span aria-label="모은 코인">🪙 <b id="coins">0</b></span><span aria-label="열린 역사 문">✦ <b id="clues">0 / 5</b></span><span id="hearts" aria-label="생명 3개">♥ ♥ ♥</span></div><div class="game-actions"><button id="sound" aria-pressed="${sound}" aria-label="배경 음악과 효과음 켜거나 끄기">♪ 음악 ${sound?'켬':'끔'}</button><button id="pause" aria-label="일시정지">Ⅱ</button><button id="exit" aria-label="처음 화면으로">⌂</button></div></div><div class="canvas-wrap"><canvas id="game" width="960" height="540" tabindex="0" aria-label="단비의 횡스크롤 역사 게임. 좌우 화살표로 이동, Space로 점프, E로 역사 문 열기."></canvas><div id="world-notice" class="world-notice" role="status">오른쪽으로 출발! 코인을 모으며 단비와 탐험해요.</div><button id="open-gate" class="gate-button" hidden>역사 문 열기 · E</button><div id="pause-layer" class="overlay" hidden><div><span class="eyebrow">잠깐 쉬어 가요</span><h2>탐험 일시정지</h2><p>단비도 나침반을 점검하고 있어요.</p><button id="resume" class="primary">계속 탐험하기 →</button></div></div><div id="quiz-layer" class="overlay quiz-overlay" hidden></div></div><div class="controls"><div class="direction"><button data-control="left" aria-label="왼쪽으로 이동">◀</button><button data-control="right" aria-label="오른쪽으로 이동">▶</button></div><div class="control-help">← → 이동 <span>·</span> Space 점프 <span>·</span> E 역사 문<br><small>${mode==='class'?'선생님이 조작하고, 역사 문에서 함께 의논해요.':'돌멩이를 점프로 피하거나 밟아요. 떨어져도 마지막 문에서 다시 시작해요.'}</small></div><button class="jump" data-control="jump" aria-label="점프">↑ 점프</button></div><div class="map-progress" aria-label="탐험 지도"><span id="map-fill"></span>${gates.map((x,i)=>`<i style="left:${x/WORLD*100}%" id="map-${i}">${i+1}</i>`).join('')}<b>훈민정음</b></div></section>`;canvas=document.getElementById('game');ctx=canvas.getContext('2d');canvas.focus();document.getElementById('open-gate').onclick=openQuiz;document.getElementById('pause').onclick=()=>setPause(!paused);document.getElementById('resume').onclick=()=>setPause(false);document.getElementById('exit').onclick=()=>{setPause(true);showInfo('<h2>탐험을 끝낼까요?</h2><p>지금까지의 코인과 문제 풀이 결과는 학습 기록에 저장해요. 캐릭터 위치는 다시 시작하면 초기화됩니다.</p><button id="confirm-exit" class="primary">처음 화면으로</button>');document.getElementById('confirm-exit').onclick=()=>{info.close();home();focusHeading();};};document.getElementById('sound').onclick=()=>{sound=!sound;const b=document.getElementById('sound');b.textContent=sound?'♪ 음악 켬':'♪ 음악 끔';b.setAttribute('aria-pressed',String(sound));syncMusic();tone();};document.querySelectorAll('[data-control]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();if(paused||quizIndex!==null||info.open)return;b.setPointerCapture(e.pointerId);keys[b.dataset.control]=true;b.classList.add('pressed');canvas.focus({preventScroll:true});});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>{keys[b.dataset.control]=false;b.classList.remove('pressed');});});last=performance.now();syncMusic();raf=requestAnimationFrame(loop);}
function setPause(value){if(scene!=='game'||quizIndex!==null)return;paused=value;clearInput();syncMusic();document.getElementById('pause-layer').hidden=!value;document.getElementById('pause').textContent=value?'▶':'Ⅱ';document.getElementById('pause').setAttribute('aria-label',value?'계속하기':'일시정지');if(value)saveLearning();if(!value)canvas.focus({preventScroll:true});else document.getElementById('resume').focus({preventScroll:true});}
function notice(t){const n=document.getElementById('world-notice');if(n)n.textContent=t;}
function sync(){document.getElementById('coins').textContent=state.count;document.getElementById('clues').textContent=`${state.solved} / 5`;const hearts=document.getElementById('hearts');hearts.textContent='♥ '.repeat(state.hearts)+'♡ '.repeat(3-state.hearts);hearts.setAttribute('aria-label',`생명 ${state.hearts}개`);document.getElementById('chapter').textContent=chapters[Math.min(4,state.solved)];document.getElementById('map-fill').style.width=`${state.player.x/WORLD*100}%`;gates.forEach((x,i)=>document.getElementById(`map-${i}`).classList.toggle('done',i<state.solved));const near=state.solved<5&&Math.abs(state.player.x+state.player.w-gates[state.solved])<85&&state.player.ground;document.getElementById('open-gate').hidden=!near||quizIndex!==null;if(near&&gatePrompt!==state.solved){gatePrompt=state.solved;notice('역사 문에 도착했어요! E키 또는 ‘역사 문 열기’를 눌러요.');}}
function loop(t){if(scene!=='game')return;const dt=(t-last)/1000;last=t;if(!paused&&quizIndex===null&&!info.open){for(const e of update(state,keys,dt)){if(e.type==='coin')tone(900);if(e.type==='jump')tone(390);if(e.type==='stomp')tone(600,.12);if(e.type==='rescue'){clearInput();notice('괜찮아요! 마지막으로 연 역사 문에서 다시 출발해요.');tone(220,.2);}if(e.type==='finish'){finish();return;}}sync();}camera=Math.max(0,Math.min(WORLD-960,state.player.x-320));draw(state,camera);raf=requestAnimationFrame(loop);}
function openQuiz(){if(scene!=='game'||paused||info.open||quizIndex!==null||state.solved===5)return;const p=state.player;if(Math.abs(p.x+p.w-gates[state.solved])>85||!p.ground)return;clearInput();quizIndex=state.solved;syncMusic();quizSolved=false;wrong=false;const q=questions[quizIndex],layer=document.getElementById('quiz-layer');layer.hidden=false;document.getElementById('open-gate').hidden=true;layer.innerHTML=`<section class="quiz-card" role="dialog" aria-modal="true" aria-labelledby="quiz-title"><div class="quiz-top"><span class="eyebrow">역사 문 ${quizIndex+1} / 5 · ${chapters[quizIndex]}</span><button id="quiz-close" aria-label="문제 닫고 탐험으로 돌아가기">✕</button></div><div class="quiz-story"><img src="assets/danbi-fox.png" alt="단비"><p>${q.story}</p></div><h2 id="quiz-title" tabindex="-1">${q.title}</h2>${mode==='class'?'<div class="discussion">우리 반 생각 나누기 · 답을 고른 이유도 이야기해 보세요.</div>':''}<div class="answers">${q.options.map((o,i)=>`<button data-answer="${i}"><span>${i+1}</span>${o}</button>`).join('')}</div><div id="feedback" role="status" aria-live="polite"></div><div class="quiz-bottom"><button id="hint">단비의 힌트</button><button id="continue" class="primary" hidden>문 열고 계속 달리기 →</button></div></section>`;document.getElementById('quiz-close').onclick=closeQuiz;document.getElementById('hint').onclick=()=>document.getElementById('feedback').innerHTML=`<p class="feedback">💡 ${q.hint}</p>`;layer.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(quizSolved)return;if(Number(b.dataset.answer)===q.answer){quizSolved=true;if(!wrong)firstTry++;b.classList.add('correct');layer.querySelectorAll('[data-answer]').forEach(a=>a.disabled=true);document.getElementById('feedback').innerHTML=`<p class="feedback"><strong>✦ 역사 문을 열었어요! 보너스 코인 +10</strong><br>${q.explain}</p>`;document.getElementById('hint').hidden=true;document.getElementById('continue').hidden=false;tone(1100,.2);}else{wrong=true;b.disabled=true;b.classList.add('wrong');document.getElementById('feedback').innerHTML=`<p class="feedback error"><strong>다시 도전해 봐요!</strong><br>${q.hint}</p>`;}});document.getElementById('continue').onclick=closeQuiz;document.getElementById('quiz-title').focus({preventScroll:true});}
function closeQuiz(){if(quizIndex===null)return;if(quizSolved){state.count+=10;unlock(state);saveLearning();notice(state.solved===5?'모든 문이 열렸어요! 오른쪽 끝 궁궐에서 훈민정음을 찾아요.':'역사 문이 열렸어요! 다음 문을 향해 달려요.');}quizIndex=null;clearInput();syncMusic();document.getElementById('quiz-layer').hidden=true;gatePrompt=-1;sync();canvas.focus({preventScroll:true});}
function finish(){stop();scene='finish';saveLearning(true);app.innerHTML=`<section class="finish"><div class="eyebrow">STAGE CLEAR · 조선의 시간여행 완료</div><div class="book" role="img" aria-label="게임 속 훈민정음 책"><span>훈민정음</span></div><h1>훈민정음을<br><em>되찾았어요!</em></h1><p>단비와 다섯 역사 문을 열고 궁궐 끝까지 도착했어요.</p><div class="results"><div><b>🪙 ${state.count}</b><span>모은 코인</span></div><div><b>5 / 5</b><span>열린 역사 문</span></div><div><b>${firstTry} / 5</b><span>첫 시도에 찾은 답</span></div></div><div class="recap"><p><strong>1443년</strong> 훈민정음 창제</p><p><strong>1446년</strong> 반포 · 해례본 간행</p><p>백성을 위한 글자 · 처음에는 28자</p></div>${mode==='class'?'<p>우리 반 이야기: 내가 세종이라면 백성의 어떤 어려움을 해결하고 싶을까요?</p>':''}<button id="again" class="primary">다시 달리기 ↗</button><button id="to-home" class="secondary">처음 화면</button><p class="small">탐험 결과는 로그인한 계정의 학습 기록에 저장됩니다. 상단에서 저장 상태를 확인해 주세요.</p></section>`;document.getElementById('again').onclick=start;document.getElementById('to-home').onclick=()=>{home();focusHeading();};focusHeading();tone(1200,.3);}
function showInfo(html){returnFocus=document.activeElement;clearInput();document.getElementById('info-content').innerHTML=html;info.showModal();syncMusic();}document.querySelector('#info .close').onclick=()=>info.close();info.addEventListener('close',()=>{clearInput();syncMusic();returnFocus?.focus({preventScroll:true});});
document.getElementById('guide').onclick=()=>showInfo('<h2>단비와 달리는 방법</h2><p><strong>← → 또는 A · D:</strong> 이동<br><strong>Space · ↑ · W:</strong> 점프<br><strong>E:</strong> 역사 문 열기<br><strong>P:</strong> 일시정지</p><p>태블릿·휴대폰은 아래 ◀ ▶와 점프 버튼을 사용해요. 이동을 누른 채 점프하면 멀리 뛰어요.</p><p>코인을 모으고 돌멩이를 점프로 넘거나 위에서 밟아요. 물에 빠지거나 부딪히면 마지막으로 연 문에서 다시 시작해요. 생명 3개를 모두 쓰면 생명이 회복돼요. 코인과 열린 문은 유지됩니다.</p><p>역사 문 다섯 개를 열고 오른쪽 끝 궁궐에 도착하면 훈민정음을 수집해요. 틀려도 힌트를 보고 다시 도전할 수 있어요.</p><p><strong>교실 모드:</strong> 선생님이 한 화면에서 조작하고, 역사 문에서 함께 의논해요. 기기 간 실시간 연결은 없어요.</p><p>탐험 시작과 함께 신나는 배경 음악이 반복 재생돼요. ♪ 음악 버튼으로 음악과 효과음을 함께 끌 수 있어요. 문제를 풀 때는 음악이 작아지고, 일시정지하거나 화면을 떠나면 멈춰요.</p><p>아이디와 비밀번호로 로그인해 탐험해요. 역사 문을 열거나 일시정지·완료하면 학습 기록을 저장해요. 진행 중인 캐릭터 위치는 새로고침하면 초기화됩니다. 비밀번호 분실 시 담당 교사에게 문의해 주세요.</p>');
document.getElementById('sources').onclick=()=>showInfo('<h2>역사 이야기의 출처</h2><p>단비, 시간여행과 유물 찾기는 창작 이야기예요. 역사 내용은 다음 자료를 참고했어요.</p><ul><li><a href="https://www.hangeul.go.kr/exhi/dailyExhibition.do?curr_menu_cd=0102010000" target="_blank" rel="noopener noreferrer">국립한글박물관 · 훈민정음, 천년의 문자 계획</a></li><li><a href="https://contents.history.go.kr/mobile/kc/view.do?levelId=kc_r300900" target="_blank" rel="noopener noreferrer">국사편찬위원회 우리역사넷 · 훈민정음</a></li></ul><p>1443년 창제와 1446년 반포·해례본 간행, 처음의 28자와 오늘날 기본 자모 24자를 구분합니다. 궁궐과 유물 그림은 게임을 위한 표현입니다.</p>');
document.getElementById('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{showInfo('<h2>화면 확대</h2><p>이 환경에서는 전체 화면을 사용할 수 없어요. 브라우저 확대 기능을 이용해 주세요.</p>');}};document.addEventListener('fullscreenchange',()=>document.getElementById('fullscreen').textContent=document.fullscreenElement?'⛶ 전체 화면 종료':'⛶ 전체 화면');
const keymap={arrowleft:'left',a:'left',arrowright:'right',d:'right',' ':'jump',arrowup:'jump',w:'jump'};
window.addEventListener('keydown',e=>{if(scene!=='game'||info.open)return;const k=e.key.toLowerCase();if(quizIndex!==null){if(k==='escape')closeQuiz();else if(k==='tab'){const items=[...document.querySelectorAll('#quiz-layer button:not([disabled]):not([hidden])')],a=items[0],b=items.at(-1);if(e.shiftKey&&(document.activeElement===a||document.activeElement.id==='quiz-title')){e.preventDefault();b.focus();}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a.focus();}}return;}if(k==='p'||k==='escape'){e.preventDefault();if(!e.repeat)setPause(!paused);return;}if(paused)return;if(keymap[k]){e.preventDefault();keys[keymap[k]]=true;}if(k==='e'){e.preventDefault();openQuiz();}});window.addEventListener('keyup',e=>{if(keymap[e.key.toLowerCase()])keys[keymap[e.key.toLowerCase()]]=false;});window.addEventListener('blur',()=>{clearInput();if(scene==='game'&&quizIndex===null)setPause(true);});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();if(scene==='game'&&quizIndex===null)setPause(true);}syncMusic();});
function rect(x,y,w,h,c,r=0){ctx.fillStyle=c;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}function text(t,x,y,size,c='#183e38',align='left'){ctx.fillStyle=c;ctx.font=`700 ${size}px "Malgun Gothic",sans-serif`;ctx.textAlign=align;ctx.fillText(t,x,y);}function hill(x,y,w,h,c){ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(x-w,y);ctx.quadraticCurveTo(x,y-h,x+w,y);ctx.closePath();ctx.fill();}function cloud(x,y){ctx.fillStyle='#ffffffed';ctx.beginPath();ctx.ellipse(x,y,50,15,0,0,7);ctx.ellipse(x+24,y-10,24,19,0,0,7);ctx.ellipse(x-18,y-9,26,21,0,0,7);ctx.fill();}function tree(x,y){rect(x-4,y-70,8,70,'#ad8146');hill(x,y-50,38,55,'#30b884');hill(x,y-75,28,45,'#64d889');}
function palace(x,y,w=250){rect(x,y-110,w,110,'#ffe9ae');for(let z=x+14;z<x+w;z+=45){rect(z,y-100,10,100,'#ef826d');rect(z+12,y-76,22,40,'#90e6f4');}rect(x+w/2-23,y-55,46,55,'#84c9ed',8);ctx.fillStyle='#387cda';ctx.beginPath();ctx.moveTo(x-28,y-110);ctx.quadraticCurveTo(x-8,y-112,x+12,y-139);ctx.lineTo(x+w/2,y-164);ctx.lineTo(x+w-12,y-139);ctx.quadraticCurveTo(x+w+8,y-112,x+w+28,y-110);ctx.closePath();ctx.fill();rect(x-25,y-111,w+50,9,'#4da9f0',3);rect(x+w/2-29,y-130,58,21,'#ffbd5c',3);text('조선',x+w/2,y-115,13,'#fff8df','center');}
function coin(x,y,t){ctx.save();ctx.translate(x,y);ctx.scale(.65+Math.abs(Math.sin(t*3+x))*.35,1);ctx.fillStyle='#ffd348';ctx.beginPath();ctx.ellipse(0,0,11,14,0,0,7);ctx.fill();ctx.strokeStyle='#c48616';ctx.lineWidth=2;ctx.stroke();rect(-2,-6,4,12,'#fff0a1',1);ctx.restore();}
function draw(s,cam){if(!ctx)return;ctx.clearRect(0,0,960,540);const bg=ctx.createLinearGradient(0,0,0,540);bg.addColorStop(0,'#8ddcff');bg.addColorStop(.72,'#dcf8ff');bg.addColorStop(1,'#f3ffdd');ctx.fillStyle=bg;ctx.fillRect(0,0,960,540);ctx.fillStyle='#ffe477';ctx.beginPath();ctx.arc(795-cam*.03,85,33,0,7);ctx.fill();for(let n=0;n<8;n++)cloud(n*230-cam*.18,65+(n%3)*25);for(let n=-1;n<10;n++){hill(n*290-cam*.25,320,210,170,'#a9eab9');hill(n*340+110-cam*.4,365,230,170,'#78dda1');}ctx.save();ctx.translate(-cam,0);for(let n=0;n<14;n++){const x=n*300;tree(x+50,430);if(n%2===0)palace(x+80,423,180);}rect(0,410,WORLD,30,'#c2f195');rect(0,FLOOR,WORLD,100,'#f4c485');rect(0,FLOOR,WORLD,12,'#53cd7c');for(let x=0;x<WORLD;x+=40){rect(x,FLOOR+12,38,22,'#eab073');rect(x+9,FLOOR+46,23,12,'#f9d49a',3);}for(const g of gaps){rect(g.x,FLOOR,g.w,100,'#47c8ee');for(let y=458;y<540;y+=20){ctx.strokeStyle='#d5faff';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(g.x+5,y);ctx.quadraticCurveTo(g.x+40,y-8,g.x+g.w-5,y);ctx.stroke();}}for(const p of platforms){rect(p.x,p.y,p.w,p.h,'#f8b65e',4);rect(p.x,p.y,p.w,7,'#50d093',3);for(let x=p.x+10;x<p.x+p.w;x+=30)rect(x,p.y+10,20,5,'#ffe2a5');}for(let x=130;x<WORLD;x+=180){if(gaps.some(g=>x>g.x-15&&x<g.x+g.w+15))continue;rect(x,FLOOR-13,3,13,'#36a86b');ctx.fillStyle=x%360<180?'#ff83b9':'#fff198';ctx.beginPath();for(let n=0;n<5;n++)ctx.ellipse(x+1+Math.cos(n*1.256)*5,FLOOR-16+Math.sin(n*1.256)*5,4,4,0,0,7);ctx.fill();ctx.fillStyle='#ffba39';ctx.beginPath();ctx.arc(x+1,FLOOR-16,3,0,7);ctx.fill();}for(const c of s.coins)if(!c.taken&&c.x>cam-20&&c.x<cam+990)coin(c.x,c.y+Math.sin(s.time*3+c.x)*3,s.time);gates.forEach((x,i)=>{const open=i<s.solved;rect(x-32,FLOOR-146,64,146,open?'#59d6b4':'#9875e2',6);rect(x-41,FLOOR-153,82,15,'#ffcf68',4);rect(x-23,FLOOR-134,46,125,open?'#bbfff099':'#7553bc',4);if(!open){ctx.strokeStyle='#ffe280';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x,FLOOR-123);ctx.lineTo(x,FLOOR-12);ctx.stroke();text('?',x,FLOOR-60,30,'#fff3b4','center');}else text('✓',x,FLOOR-70,27,'#fffbdc','center');rect(x-27,FLOOR-184,54,24,'#fff5d7',7);text(`${i+1}번 문`,x,FLOOR-167,12,'#335d4e','center');});for(const e of s.enemies){if(e.x<-100)continue;ctx.fillStyle='#869aca';ctx.beginPath();ctx.ellipse(e.x+20,FLOOR-16,22,16,0,0,7);ctx.fill();rect(e.x+9,FLOOR-25,5,6,'#fff5da',2);rect(e.x+25,FLOOR-25,5,6,'#fff5da',2);rect(e.x+10,FLOOR-23,3,4,'#34463c');rect(e.x+26,FLOOR-23,3,4,'#34463c');}palace(3600,FLOOR,270);rect(3740,FLOOR-78,50,60,'#d8af5f',4);rect(3755,FLOOR-73,22,45,'#fff2cc',2);text('훈',3766,FLOOR-54,14,'#694e28','center');text('민',3766,FLOOR-34,14,'#694e28','center');text('목표 · 훈민정음',3740,FLOOR-190,18,'#355d4e','center');const p=s.player,a=pose(p);ctx.save();ctx.translate(p.x+p.w/2,p.y+p.h);if(s.invincible>0&&Math.floor(s.time*12)%2)ctx.globalAlpha=.55;ctx.scale(p.face*a.sx,a.sy);if(a.frame>=0&&motion.complete&&motion.naturalWidth){const f=frames[a.frame],scale=100/479;ctx.drawImage(motion,f.x,f.y,f.w,f.h,-f.w*scale/2,-f.h*scale+a.bob,f.w*scale,f.h*scale);}else if(sprite.complete&&sprite.naturalWidth){ctx.drawImage(sprite,-48,-100+a.bob,96,102);}else{rect(-20,-p.h,40,p.h,'#ff8249',16);text('단비',0,-20,12,'#163d37','center');}ctx.restore();rect(p.x+p.w/2-24,p.y+p.h-130,48,20,'#fffef6',9);text('단비',p.x+p.w/2,p.y+p.h-116,12,'#5444a0','center');for(const a of s.particles)text(a.text,a.x,a.y-a.age*45,18,'#99621d');ctx.restore();if(scene==='home'){rect(18,18,128,34,'#fffbdfdd',12);text('🪙 12   ✦ 0/5',30,42,17);}}
home();


